V C_PrimalMineTests::m_blast(const Args& A) {
    V L_key = A.get(0, SY("key"), nullptr, "blast");
    V L_distances = A.get(1, SY("distances"), nullptr, "blast");
    V L_b;
    V L_others;
    V L_p;
    V L_trigger;
    V L_unused;
    L_b = m_battle(Args({}, {{SY("plants"), V::list({L_key})}}));
    (void)(m_park_heroes(Args{L_b}));
    L_p = m_deploy(Args{L_b, SV("plant"), L_key, V(12.0)});
    setm(L_p, &Obj::埋藏, SV("埋藏"), V(0.0));
    (void)(m_ticks(Args{L_b, V(260.0)}));
    L_trigger = m_zombie(Args({L_b, SV("zombie:普通僵尸"), V(12.6)}, {{SY("hold"), V(false)}}));
    setm(L_trigger, &Obj::移速, SV("移速"), V(0.001));
    L_others = [&]() -> V { V out_ = V::list(); V L_d; { V it1_ = py::iter_list(L_distances); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_d = it1_.idx(int64_t(i1_)); out_.append(m_zombie(Args{L_b, SV("zombie:普通僵尸"), (V(12.5) + L_d)})); }}return out_; }();
    { const int64_t b2_ = 0, e2_ = (int64_t)(V(400.0)).num(), s2_ = 1;
    for (int64_t i2_ = b2_; s2_ > 0 ? i2_ < e2_ : i2_ > e2_; i2_ += s2_) {
        L_unused = V(double(i2_)); 
        (void)(callm(L_b, SY("_step_original"), Args{}));
        if ((py::in(SV("死"), L_p) || (py::m_get_slot(L_p, &Obj::植物血, SV("植物血"), V(1.0)) <= V(0.0)))) {
            break;
        }
    }}
    (void)(m_ticks(Args{L_b, V(5.0)}));
    return V::tuple({L_trigger, L_others});
    return V::none();
}

