V C_GrenadierTests::m_setup(const Args& A) {
    V L_umbrella = (A.size() > 0 || A.has_kw(SY("umbrella"))) ? A.get(0, SY("umbrella"), nullptr) : V(V(false));
    V L_b;
    V L_cheap;
    V L_grenadier;
    V L_p;
    V L_plants;
    V L_rich;
    V L_shield;
    L_plants = V::list({SV("plant:豌豆射手"), SV("plant:机枪射手"), SV("plant:坚果"), SV("plant:萝卜伞")});
    L_b = m_battle(Args({}, {{SY("plants"), L_plants}, {SY("zombies"), V::list({SV("zombie:脑光墓碑"), SV("zombie:掷弹兵僵尸")})}}));
    (void)(m_park_heroes(Args({L_b}, {{SY("plant_col"), V(2.0)}, {SY("zombie_col"), V(28.0)}})));
    L_cheap = m_deploy(Args{L_b, SV("plant"), SV("plant:豌豆射手"), V(14.0)});
    L_rich = m_deploy(Args{L_b, SV("plant"), SV("plant:机枪射手"), V(13.0)});
    { V it1_ = py::iter_list(V::tuple({L_cheap, L_rich}));
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        L_p = it1_.idx(int64_t(i1_)); 
        setm(L_p, &Obj::射cd, SV("射cd"), pow(V(10.0), V(9.0)));
    }}
    L_shield = ((L_umbrella).truthy() ? V(m_deploy(Args{L_b, SV("plant"), SV("plant:萝卜伞"), V(12.0)})) : V(V::none()));
    L_grenadier = m_zombie(Args({L_b, SV("zombie:掷弹兵僵尸"), V(18.5)}, {{SY("hold"), V(false)}}));
    setm(L_grenadier, &Obj::移速, SV("移速"), V(0.001));
    return V::tuple({L_b, L_cheap, L_rich, L_shield, L_grenadier});
    return V::none();
}

