    V L_b;
    V L_before;
    V L_cluster;
    V L_far;
    V L_latest;
    V L_merged;
    V L_plant;
    V L_sun_pick_radius;
    V L_sun_size;
    L_sun_size = V::func(pm_world_view::f_sun_size);
