    L_b = m_battle(Args{});
    (void)(m_park_heroes(Args({L_b}, {{SY("plant_col"), V(1.0)}, {SY("zombie_col"), V(28.0)}})));
    L_cluster = [&]() -> V { V out_ = V::list(); V L_i; { V it1_ = py::iter_list(py::range((int64_t)(V(4.0)).num())); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_i = it1_.idx(int64_t(i1_)); out_.append(callm(L_b, SY("resource"), Args{SV("plant"), V(25.0), ((V(10.0) + (L_i * V(0.15))) * pvz::getattr(L_b, SY("tile"))), (V(8.0) * pvz::getattr(L_b, SY("tile"))), SV("sky")})); }}return out_; }();
    (void)(py::m_append(L_cluster, callm(L_b, SY("resource"), Args{SV("plant"), V(15.0), (V(10.3) * pvz::getattr(L_b, SY("tile"))), (V(8.0) * pvz::getattr(L_b, SY("tile"))), SV("native_producer")})));
    L_far = callm(L_b, SY("resource"), Args{SV("plant"), V(25.0), (V(20.0) * pvz::getattr(L_b, SY("tile"))), (V(8.0) * pvz::getattr(L_b, SY("tile"))), SV("sky")});
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    L_latest = py::max_it([&]() -> V { V out_ = V::list(); V L_r; { V it2_ = py::iter_list(L_cluster); for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) { L_r = it2_.idx(int64_t(i2_)); if (!(py::in(L_r, pvz::getattr(L_b, SY("resources"))))) continue; out_.append(rd(rd(pvz::getattr(L_b, SY("resources")), L_r), SV("born"))); }}return out_; }(), py::Key(), V());
    (void)(callm(L_b, SY("step"), Args{V(2.0)}));
    L_plant = [&]() -> V { V out_ = V::list(); V L_r; { V it3_ = py::iter_list(callm(pvz::getattr(L_b, SY("resources")), SY("values"), Args{})); for (size_t i3_ = 0; i3_ < it3_.len(); ++i3_) { L_r = it3_.idx(int64_t(i3_)); if (!((rd(L_r, SV("side")) == SV("plant")))) continue; out_.append(L_r); }}return out_; }();
    (void)(m_assertEqual(Args{V(2.0), py::len(L_plant)}));
    (void)(m_assertEqual(Args{V(115.0), py::sum_it([&]() -> V { V out_ = V::list(); V L_r; { V it4_ = py::iter_list(L_plant); for (size_t i4_ = 0; i4_ < it4_.len(); ++i4_) { L_r = it4_.idx(int64_t(i4_)); if (!((rd(L_r, SV("id")) != L_far))) continue; out_.append(rd(L_r, SV("amount"))); }}return out_; }())}));
    (void)(m_assertIn(Args{L_far, pvz::getattr(L_b, SY("resources"))}));
    L_merged = py::next([&]() -> V { V out_ = V::list(); V L_r; { V it5_ = py::iter_list(L_plant); for (size_t i5_ = 0; i5_ < it5_.len(); ++i5_) { L_r = it5_.idx(int64_t(i5_)); if (!((rd(L_r, SV("id")) != L_far))) continue; out_.append(L_r); }}return out_; }());
    (void)(m_assertGreaterEqual(Args{rd(L_merged, SV("born")), L_latest}));
