        (void)(m_assertTrue(Args{pvz::getattr(pvz::getattr(L_app, SY("result_animation")), SY("active"))}));
        (void)(m_assertEqual(Args{L_before, (L_state_hash).call(Args{pvz::getattr(pvz::getattr(L_app, SY("room")), SY("battle"))})}));
