V C_GateIndexTests::m_test_potato_and_belt_indexes_follow_the_board(const Args& A) {
    V L_BELT_STRIDE;
    V L_b;
    V L_col;
    V L_p64;
    V L_potato;
    V L_row;
    L_b = m_battle(Args({}, {{SY("plants"), V::list({SV("plant:甜薯")})}}));
    L_p64 = pvz::getattr(pvz::getattr(L_b, SY("content")), SY("pvp64"));
    (void)(m_assertEqual(Args{V::tuple({V::list({}), V(false), py::set_it()}), V::tuple({pvz::getattr(L_p64, SY("potato_points")), pvz::getattr(L_p64, SY("potatoes_dirty")), pvz::getattr(L_p64, SY("belt_keys"))})}));
    (void)(callm(rd(rd(pvz::getattr(L_b, SY("players")), SV("plant")), SV("cooldowns")), SY("clear"), Args{}));
    L_potato = m_deploy(Args{L_b, SV("plant"), SV("plant:甜薯"), V(12.0)});
    (void)(m_assertTrue(Args{pvz::getattr(L_p64, SY("potatoes_dirty"))}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertFalse(Args{pvz::getattr(L_p64, SY("potatoes_dirty"))}));
    { V ut1_ = py::as_seq(rdm(L_potato, &Obj::坐标, SV("坐标"))); L_row = ut1_.idx(0); L_col = ut1_.idx(1); } 
    (void)(m_assertEqual(Args{V::list({V::tuple({((L_col + V(0.5)) * pvz::getattr(L_b, SY("tile"))), ((L_row + V(0.5)) * pvz::getattr(L_b, SY("tile")))})}), pvz::getattr(L_p64, SY("potato_points"))}));
    setm(L_potato, &Obj::植物血, SV("植物血"), V(0.0));
    setm(L_potato, &Obj::死, SV("死"), V(0.0));
    (void)(callm(L_b, SY("step"), Args{V(3.0)}));
    (void)(m_assertEqual(Args{V::list({}), pvz::getattr(L_p64, SY("potato_points"))}));
    pvz::setitem(rd(rd(pvz::getattr(L_b, SY("g")), SV("ditu")), V(8.0)), V(20.0), py_dict({{SV("方块"), SV("梯子块")}, {SV("里方块"), SV("空")}, {SV("_pvp_belt"), V(true)}}));
    (void)(callm(L_b, SY("_sync_terrain"), Args{}));
    L_BELT_STRIDE = pm_pvp64_content::BELT_STRIDE;
    (void)(m_assertEqual(Args{V::set({((V(8.0) * L_BELT_STRIDE) + V(20.0))}), pvz::getattr(L_p64, SY("belt_keys"))}));
    return V::none();
}

